import React from 'react';
import {
  LineChart, Line, XAxis, YAxis, Tooltip, CartesianGrid, Legend
} from 'recharts';
import { useTranslation } from 'react-i18next';

export default function LineChartComponent({ data, provinces }) {
  const { t } = useTranslation();
  if (!data.length) return null;

  const dates = [...new Set(data.map(d => d.date))].sort();
  const chartData = dates.map(date => {
    const entry = { date };
    provinces.forEach(prov => {
      const pt = data.find(d => d.date === date && d.province === prov);
      entry[prov] = pt ? pt.value : null;
    });
    return entry;
  });

  // Define distinct colors for each province
  const provinceColors = {
    'Ontario': '#8884d8',
    'Quebec': '#82ca9d', 
    'British Columbia': '#ffc658'
  };

  return (
    <div>
      <h2>{t('line_chart_title', { type: data[0]?.type ? t(`food_types.${data[0].type}`) : '' })}</h2>
      <LineChart width={700} height={300} data={chartData}>
        <CartesianGrid strokeDasharray="3 3" />
        <XAxis dataKey="date" />
        <YAxis 
          domain={['dataMin - 0.1', 'dataMax + 0.1']}
          tickFormatter={(value) => value.toFixed(2)}
        />
        <Tooltip 
          formatter={(value, name) => [`$${value.toFixed(2)}`, name]}
          labelFormatter={(label) => `${label}`}
        />
        <Legend />
        {provinces.map(prov => (
          <Line 
            key={prov} 
            type="monotone" 
            dataKey={prov} 
            name={prov} 
            stroke={provinceColors[prov]}
            strokeWidth={3}
            dot={{ fill: provinceColors[prov], strokeWidth: 2, r: 4 }}
            activeDot={{ r: 6, strokeWidth: 2 }}
          />
        ))}
      </LineChart>
    </div>
  );
}
